import { act } from 'preact/test-utils';
import { createElement, render } from 'preact';
import { setupScratch, teardown } from '../../../test/_util/helpers';
import { useEffect, useState } from 'preact/hooks';

/** @jsx createElement */

describe('issue #3567', () => {
	let scratch;

	beforeEach(() => {
		scratch = setupScratch();
	});

	afterEach(() => {
		teardown(scratch);
	});

	it('does not run effect cleanup when settling state during render', () => {
		const calls = [];
		let click;

		function Foo() {
			const [a, setA] = useState(false);

			useEffect(() => {
				calls.push('effect');
				return () => calls.push('cleanup');
			}, []);

			click = () => setA(true);

			setA(false);

			return <p>{String(a)}</p>;
		}

		act(() => {
			render(<Foo />, scratch);
		});
		expect(calls).to.deep.equal(['effect']);

		act(() => {
			click();
		});
		expect(calls).to.deep.equal(['effect']);
		expect(scratch.innerHTML).to.equal('<p>true</p>');
	});

	it('settles state set during render without rerunning committed effects', () => {
		const calls = [];
		let set;

		function Comp({ i }) {
			const [greeting, setGreeting] = useState('hi');
			set = setGreeting;

			useEffect(() => {
				calls.push('doing effect' + greeting);
				return () => {
					calls.push('cleaning up' + greeting);
				};
			}, [greeting]);

			if (i === 2) {
				setGreeting('bye');
			}

			return <p>{greeting}</p>;
		}

		act(() => {
			render(<Comp />, scratch);
		});
		expect(calls.length).to.equal(1);
		expect(calls).to.deep.equal(['doing effecthi']);

		act(() => {
			render(<Comp i={2} />, scratch);
		});
		expect(scratch.innerHTML).to.equal('<p>bye</p>');
	});
});

